const puppeteer = require('/usr/local/lib/node_modules/@mermaid-js/mermaid-cli/node_modules/puppeteer');
const fs = require('fs');
const path = require('path');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { margin: 0; background: #ECEFF1; font-family: Arial, sans-serif; }
  #chart { width: 1700px; height: 950px; }
</style>
<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
</head>
<body>
<div id="chart"></div>
<script>
const nodesOrdered = [
  ['oil',            'Oil',                      '#7B3F00'],
  ['coal',           'Coal',                     '#3D3D3D'],
  ['natural_gas',    'Natural Gas',              '#B5651D'],
  ['nuclear',        'Nuclear',                  '#6A0DAD'],
  ['hydro',          'Hydropower',               '#1565C0'],
  ['wind',           'Wind',                     '#2E7D32'],
  ['solar',          'Solar',                    '#F9A825'],
  ['biomass',        'Biomass',                  '#33691E'],
  ['geothermal',     'Geothermal',               '#00838F'],
  ['thermal_power',  'Thermal Power Generation', '#BF360C'],
  ['refining',       'Refining & Petrochemicals','#6D4C41'],
  ['direct_use',     'Direct Use',               '#546E7A'],
  ['electricity_grid','Electricity Grid',         '#0277BD'],
  ['transport',      'Transport',                '#4527A0'],
  ['industry',       'Industry',                 '#4E342E'],
  ['buildings',      'Buildings',                '#0288D1'],
  ['agriculture',    'Agriculture',              '#388E3C'],
  ['other',          'Other',                    '#78909C'],
  ['waste_heat',     'Waste / Rejected Heat',    '#D84315'],
];

const nodeIndex = {};
nodesOrdered.forEach(([id, label, color], i) => { nodeIndex[id] = i; });
const nodeLabels = nodesOrdered.map(n => n[1]);
const nodeColors = nodesOrdered.map(n => n[2]);

const flows = [
  ['coal',           'thermal_power',    96.5],
  ['natural_gas',    'thermal_power',    42.8],
  ['oil',            'thermal_power',     8.2],
  ['nuclear',        'thermal_power',    29.4],
  ['oil',            'refining',        162.3],
  ['natural_gas',    'refining',         18.5],
  ['natural_gas',    'direct_use',       80.2],
  ['coal',           'direct_use',       60.8],
  ['biomass',        'direct_use',       42.6],
  ['hydro',          'electricity_grid', 15.8],
  ['wind',           'electricity_grid',  8.4],
  ['solar',          'electricity_grid',  5.9],
  ['geothermal',     'electricity_grid',  1.0],
  ['thermal_power',  'electricity_grid', 68.2],
  ['thermal_power',  'waste_heat',      108.7],
  ['refining',       'transport',       118.6],
  ['refining',       'industry',         35.4],
  ['refining',       'waste_heat',       26.8],
  ['electricity_grid','buildings',       38.2],
  ['electricity_grid','industry',        36.8],
  ['electricity_grid','transport',        4.1],
  ['electricity_grid','agriculture',      7.6],
  ['electricity_grid','other',           12.6],
  ['direct_use',     'industry',         82.4],
  ['direct_use',     'buildings',        56.7],
  ['direct_use',     'agriculture',      12.3],
  ['direct_use',     'waste_heat',       32.2],
];

function hexToRgba(hex, alpha) {
  const r = parseInt(hex.slice(1,3), 16);
  const g = parseInt(hex.slice(3,5), 16);
  const b = parseInt(hex.slice(5,7), 16);
  return \`rgba(\${r},\${g},\${b},\${alpha})\`;
}

const srcIdx    = flows.map(f => nodeIndex[f[0]]);
const tgtIdx    = flows.map(f => nodeIndex[f[1]]);
const values    = flows.map(f => f[2]);
const linkColors = flows.map(([src, tgt]) => {
  if (tgt === 'waste_heat') return 'rgba(216,67,21,0.58)';
  const srcColor = nodesOrdered[nodeIndex[src]][2];
  const alpha = ['oil','coal','natural_gas'].includes(src) ? 0.45 : 0.35;
  return hexToRgba(srcColor, alpha);
});

const data = [{
  type: 'sankey',
  arrangement: 'snap',
  node: {
    pad: 20,
    thickness: 24,
    line: { color: '#455A64', width: 0.7 },
    label: nodeLabels,
    color: nodeColors,
    hovertemplate: '<b>%{label}</b><br>Total: %{value:.1f} EJ<extra></extra>',
  },
  link: {
    source: srcIdx,
    target: tgtIdx,
    value: values,
    color: linkColors,
    hovertemplate: '%{source.label} → %{target.label}<br><b>%{value:.1f} EJ</b><extra></extra>',
  },
  textfont: { size: 11.5, color: '#ECEFF1', family: 'Arial' },
}];

const layout = {
  title: {
    text: '<b>Global Energy Flow 2022</b><br><span style="font-size:13px;color:#607D8B;">Primary Sources → Transformation → End-Use Sectors  |  All values in Exajoules (EJ)</span>',
    font: { size: 21, color: '#1A237E', family: 'Arial Black' },
    x: 0.5,
    xanchor: 'center',
    y: 0.985,
  },
  annotations: [
    { x: 0.0, y: 1.055, text: '<b>PRIMARY ENERGY SOURCES</b>', showarrow: false, xref: 'paper', yref: 'paper', font: { size: 11, color: '#424242' }, xanchor: 'left' },
    { x: 0.39, y: 1.055, text: '<b>TRANSFORMATION</b>', showarrow: false, xref: 'paper', yref: 'paper', font: { size: 11, color: '#424242' }, xanchor: 'center' },
    { x: 0.83, y: 1.055, text: '<b>END-USE SECTORS</b>', showarrow: false, xref: 'paper', yref: 'paper', font: { size: 11, color: '#424242' }, xanchor: 'center' },
    {
      x: 0.5, y: -0.042,
      text: '■ Waste/Rejected Heat (~167.7 EJ) exceeds total renewable inputs (~73.7 EJ)   |   ■ Fossil fuels (Oil, Coal, Natural Gas) dominate total energy flow   |   Source: IEA / LLNL-style energy balance, 2022 approx.',
      showarrow: false, xref: 'paper', yref: 'paper',
      font: { size: 10, color: '#546E7A' }, xanchor: 'center',
    },
  ],
  font: { size: 11, family: 'Arial' },
  width: 1700,
  height: 950,
  paper_bgcolor: '#ECEFF1',
  plot_bgcolor: '#ECEFF1',
  margin: { l: 25, r: 25, t: 95, b: 55 },
};

Plotly.newPlot('chart', data, layout, { displayModeBar: false, responsive: false });
</script>
</body>
</html>`;

fs.writeFileSync('/tmp/sankey.html', html);

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/root/.cache/puppeteer/chrome/linux-131.0.6778.204/chrome-linux64/chrome',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1700, height: 950, deviceScaleFactor: 2 });
  await page.goto('file:///tmp/sankey.html', { waitUntil: 'networkidle0', timeout: 30000 });
  await page.waitForTimeout(2000);
  await page.screenshot({ path: '/app/output/result.png', fullPage: false });
  await browser.close();
  console.log('Done: /app/output/result.png');
})();

